// SLOP: Fully generated by Claude

//go:build goexperiment.simd && cgo

// tests comparing every function in pffft_simd.go with its counterpart in pffft.c.
// run with:
//
//	GOEXPERIMENT=simd GODEBUG=simd=128 go test ./pffft
package pffft

import (
	"fmt"
	"math"
	"math/rand/v2"
	"simd"
	"testing"

	"github.com/neputevshina/nanowarp/pffft/internal/cref"
)

const (
	vlen = 4  // floats per vector
	cpad = 16 // extra vectors after every buffer passed to C, so overruns don't corrupt the heap
)

// tolerance relative to the largest magnitude in the expected result
const tol = 1e-5

var realSizes = []int{32, 64, 96, 128, 160, 192, 256, 384, 480, 512, 640, 768, 960, 1024, 1536, 2048, 2400, 4096, 4800}
var complexSizes = []int{16, 32, 48, 64, 80, 96, 128, 240, 256, 400, 512, 768, 1024, 2048}

// the simd rewriter of go1.27.2 injects an import of simd/internal/bridge into every
// file with functions that depend on the vector size, and fails the build if none of
// the specialized code ends up using it. this function makes sure something does.
func zeroVec() reg { return simd.BroadcastFloat32s(0) }

func newRng() *rand.Rand { return rand.New(rand.NewPCG(1, 2)) }

func vecs(n int) []reg { return make([]reg, n) }

func randVecs(rng *rand.Rand, n int) []reg {
	v := vecs(n)
	f := degrade(v)
	for i := range f {
		f[i] = float32(rng.Float64()*2 - 1)
	}
	return v
}

func randFloats(rng *rand.Rand, n int) []float32 {
	f := make([]float32, n)
	for i := range f {
		f[i] = float32(rng.Float64()*2 - 1)
	}
	return f
}

func cloneVecs(v []reg) []reg { return append(vecs(0), v...) }

// cbuf returns an aligned buffer of n vectors with room for overruns after it.
func cbuf(n int) []float32 { return degrade(vecs(n + cpad))[:n*vlen] }

// cclone copies v into a fresh C buffer.
func cclone(v []reg) []float32 {
	b := cbuf(len(v))
	copy(b, degrade(v))
	return b
}

// fclone copies f into a fresh aligned buffer of the same length.
func fclone(f []float32) []float32 {
	b := degrade(vecs((len(f) + vlen - 1) / vlen))[:len(f)]
	copy(b, f)
	return b
}

func flat(v ...reg) []float32 {
	out := make([]float32, 0, len(v)*vlen)
	for _, x := range v {
		var a [vlen]float32
		x.Store(a[:])
		out = append(out, a[:]...)
	}
	return out
}

// cmp reports a mismatch between got and want. with exact set, every element must be
// bit-identical, otherwise the error is measured relative to the largest element of want.
func cmp(t *testing.T, name string, got, want []float32, exact bool) bool {
	t.Helper()
	if len(got) != len(want) {
		t.Errorf("%s: length mismatch: go %d, c %d", name, len(got), len(want))
		return false
	}
	scale := 1.0
	for _, w := range want {
		scale = math.Max(scale, math.Abs(float64(w)))
	}
	nbad, first := 0, -1
	maxerr := 0.0
	for i := range got {
		g, w := float64(got[i]), float64(want[i])
		bad := false
		if exact {
			bad = math.Float32bits(got[i]) != math.Float32bits(want[i])
		} else {
			e := math.Abs(g-w) / scale
			bad = math.IsNaN(g) || e > tol
			if !math.IsNaN(e) {
				maxerr = math.Max(maxerr, e)
			}
		}
		if bad {
			if first < 0 {
				first = i
			}
			nbad++
		}
	}
	if nbad > 0 {
		hi := min(first+8, len(got))
		t.Errorf("%s: %d/%d elements differ (max rel err %.3g), first at %d:\n go %v\n  c %v",
			name, nbad, len(got), maxerr, first, got[first:hi], want[first:hi])
		return false
	}
	return true
}

func cmpInts(t *testing.T, name string, got, want []int) bool {
	t.Helper()
	if fmt.Sprint(got) != fmt.Sprint(want) {
		t.Errorf("%s:\n go %v\n  c %v", name, got, want)
		return false
	}
	return true
}

// catch turns a panic in f into a test error.
func catch(t *testing.T, name string, f func()) (ok bool) {
	t.Helper()
	defer func() {
		if r := recover(); r != nil {
			t.Errorf("%s: go panicked: %v", name, r)
			ok = false
		}
	}()
	f()
	return true
}

func TestVectorOps(t *testing.T) {
	rng := newRng()
	for _ = range 100 {
		v := randVecs(rng, 4)
		f := degrade(v)
		a, b, c, d := f[0:4], f[4:8], f[8:12], f[12:16]
		s := float32(rng.Float64()*2 - 1)
		out, out2 := cbuf(1), cbuf(1)

		cref.Vadd(a, b, out)
		cmp(t, "vadd", flat(vadd(v[0], v[1])), out, true)
		cref.Vsub(a, b, out)
		cmp(t, "vsub", flat(vsub(v[0], v[1])), out, true)
		cref.Vmul(a, b, out)
		cmp(t, "vmul", flat(vmul(v[0], v[1])), out, true)
		cref.Vmadd(a, b, c, out)
		cmp(t, "vmadd", flat(vmadd(v[0], v[1], v[2])), out, false)
		cref.Svmul(s, a, out)
		cmp(t, "svmul", flat(svmul(s, v[0])), out, true)
		cref.LdPs1(s, out)
		cmp(t, "ld_ps1", flat(ld_ps1(s)), out, true)
		cref.Vswaphl(a, b, out)
		cmp(t, "vswaphl", flat(vswaphl(v[0], v[1])), out, true)

		cref.Interleave2(a, b, out, out2)
		g1, g2 := interleave2(v[0], v[1])
		cmp(t, "interleave2", flat(g1, g2), append(fclone(out), out2...), true)
		cref.Uninterleave2(a, b, out, out2)
		g1, g2 = uninterleave2(v[0], v[1])
		cmp(t, "uninterleave2", flat(g1, g2), append(fclone(out), out2...), true)

		x := fclone(f)
		cref.Vtranspose4(x)
		r0, r1, r2, r3 := vtranspose4(v[0], v[1], v[2], v[3])
		cmp(t, "vtranspose4", flat(r0, r1, r2, r3), x, true)

		ar, ai := fclone(a), fclone(b)
		cref.Vcplxmul(ar, ai, c, d)
		gr, gi := vcplxmul(v[0], v[1], v[2], v[3])
		cmp(t, "vcplxmul", flat(gr, gi), append(ar, ai...), false)
		ar, ai = fclone(a), fclone(b)
		cref.Vcplxmulconj(ar, ai, c, d)
		gr, gi = vcplxmulconj(v[0], v[1], v[2], v[3])
		cmp(t, "vcplxmulconj", flat(gr, gi), append(ar, ai...), false)

		if t.Failed() {
			return
		}
	}
}

// pass describes a single radix pass as used by a real plan.
type pass struct{ ip, ido, l1 int }

// passes collects the distinct radix passes of every plan in sizes. for complex plans
// ido is counted in vectors, as passed to passfN_ps.
func passes(sizes []int, real bool) []pass {
	seen := map[pass]bool{}
	var out []pass
	for _, n := range sizes {
		s := cref.NewSetup(n, real)
		ifac := s.Ifac()
		nv := n / vlen
		l1 := 1
		for k1 := 1; k1 <= ifac[1]; k1++ {
			ip := ifac[k1+1]
			l2 := ip * l1
			ido := nv / l2
			if !real {
				ido *= 2
			}
			p := pass{ip, ido, l1}
			if !seen[p] {
				seen[p] = true
				out = append(out, p)
			}
			l1 = l2
		}
	}
	return out
}

// radixFunc runs one pass in both implementations: wa holds ip-1 twiddle arrays.
type radixFunc struct {
	name string
	real bool
	gof  func(ido, l1 int, cc, ch []reg, wa [][]float32, fsign float32)
	cf   func(ido, l1 int, cc, ch []float32, wa [][]float32, fsign float32)
}

func TestRadix(t *testing.T) {
	funcs := map[int][]radixFunc{
		2: {
			{"passf2_ps", false,
				func(ido, l1 int, cc, ch []reg, wa [][]float32, fs float32) { passf2_ps(ido, l1, cc, ch, wa[0], fs) },
				func(ido, l1 int, cc, ch []float32, wa [][]float32, fs float32) {
					cref.Passf2(ido, l1, cc, ch, wa[0], fs)
				}},
			{"radf2_ps", true,
				func(ido, l1 int, cc, ch []reg, wa [][]float32, _ float32) { radf2_ps(ido, l1, cc, ch, wa[0]) },
				func(ido, l1 int, cc, ch []float32, wa [][]float32, _ float32) { cref.Radf2(ido, l1, cc, ch, wa[0]) }},
			{"radb2_ps", true,
				func(ido, l1 int, cc, ch []reg, wa [][]float32, _ float32) { radb2_ps(ido, l1, cc, ch, wa[0]) },
				func(ido, l1 int, cc, ch []float32, wa [][]float32, _ float32) { cref.Radb2(ido, l1, cc, ch, wa[0]) }},
		},
		3: {
			{"passf3_ps", false,
				func(ido, l1 int, cc, ch []reg, wa [][]float32, fs float32) {
					passf3_ps(ido, l1, cc, ch, wa[0], wa[1], fs)
				},
				func(ido, l1 int, cc, ch []float32, wa [][]float32, fs float32) {
					cref.Passf3(ido, l1, cc, ch, wa[0], wa[1], fs)
				}},
			{"radf3_ps", true,
				func(ido, l1 int, cc, ch []reg, wa [][]float32, _ float32) { radf3_ps(ido, l1, cc, ch, wa[0], wa[1]) },
				func(ido, l1 int, cc, ch []float32, wa [][]float32, _ float32) {
					cref.Radf3(ido, l1, cc, ch, wa[0], wa[1])
				}},
			{"radb3_ps", true,
				func(ido, l1 int, cc, ch []reg, wa [][]float32, _ float32) { radb3_ps(ido, l1, cc, ch, wa[0], wa[1]) },
				func(ido, l1 int, cc, ch []float32, wa [][]float32, _ float32) {
					cref.Radb3(ido, l1, cc, ch, wa[0], wa[1])
				}},
		},
		4: {
			{"passf4_ps", false,
				func(ido, l1 int, cc, ch []reg, wa [][]float32, fs float32) {
					passf4_ps(ido, l1, cc, ch, wa[0], wa[1], wa[2], fs)
				},
				func(ido, l1 int, cc, ch []float32, wa [][]float32, fs float32) {
					cref.Passf4(ido, l1, cc, ch, wa[0], wa[1], wa[2], fs)
				}},
			{"radf4_ps", true,
				func(ido, l1 int, cc, ch []reg, wa [][]float32, _ float32) {
					radf4_ps(ido, l1, cc, ch, wa[0], wa[1], wa[2])
				},
				func(ido, l1 int, cc, ch []float32, wa [][]float32, _ float32) {
					cref.Radf4(ido, l1, cc, ch, wa[0], wa[1], wa[2])
				}},
			{"radb4_ps", true,
				func(ido, l1 int, cc, ch []reg, wa [][]float32, _ float32) {
					radb4_ps(ido, l1, cc, ch, wa[0], wa[1], wa[2])
				},
				func(ido, l1 int, cc, ch []float32, wa [][]float32, _ float32) {
					cref.Radb4(ido, l1, cc, ch, wa[0], wa[1], wa[2])
				}},
		},
		5: {
			{"passf5_ps", false,
				func(ido, l1 int, cc, ch []reg, wa [][]float32, fs float32) {
					passf5_ps(ido, l1, cc, ch, wa[0], wa[1], wa[2], wa[3], fs)
				},
				func(ido, l1 int, cc, ch []float32, wa [][]float32, fs float32) {
					cref.Passf5(ido, l1, cc, ch, wa[0], wa[1], wa[2], wa[3], fs)
				}},
			{"radf5_ps", true,
				func(ido, l1 int, cc, ch []reg, wa [][]float32, _ float32) {
					radf5_ps(ido, l1, cc, ch, wa[0], wa[1], wa[2], wa[3])
				},
				func(ido, l1 int, cc, ch []float32, wa [][]float32, _ float32) {
					cref.Radf5(ido, l1, cc, ch, wa[0], wa[1], wa[2], wa[3])
				}},
			{"radb5_ps", true,
				func(ido, l1 int, cc, ch []reg, wa [][]float32, _ float32) {
					radb5_ps(ido, l1, cc, ch, wa[0], wa[1], wa[2], wa[3])
				},
				func(ido, l1 int, cc, ch []float32, wa [][]float32, _ float32) {
					cref.Radb5(ido, l1, cc, ch, wa[0], wa[1], wa[2], wa[3])
				}},
		},
	}

	rng := newRng()
	for _, real := range []bool{true, false} {
		sizes := realSizes
		if !real {
			sizes = complexSizes
		}
		for _, p := range passes(sizes, real) {
			for _, f := range funcs[p.ip] {
				if f.real != real {
					continue
				}
				fsigns := []float32{0}
				if !real {
					fsigns = []float32{-1, 1}
				}
				for _, fs := range fsigns {
					name := fmt.Sprintf("%s/ido=%d,l1=%d,fsign=%v", f.name, p.ido, p.l1, fs)
					t.Run(name, func(t *testing.T) {
						n := p.ido * p.l1 * p.ip
						cc := randVecs(rng, n)
						wa := make([][]float32, p.ip-1)
						for i := range wa {
							wa[i] = randFloats(rng, p.ido)
						}
						gch := vecs(n)
						if !catch(t, f.name, func() { f.gof(p.ido, p.l1, cloneVecs(cc), gch, wa, fs) }) {
							return
						}
						cch := cbuf(n)
						f.cf(p.ido, p.l1, cclone(cc), cch, wa, fs)
						cmp(t, f.name, degrade(gch), cch, false)
					})
				}
			}
		}
	}
}

// drivers are given the twiddles and factorization computed by C, so that only the
// driver logic itself is compared.

func which(o []reg, w1, w2 []reg) int {
	switch &o[0] {
	case &w1[0]:
		return 0
	case &w2[0]:
		return 1
	}
	return -1
}

func testRealDriver(t *testing.T, name string, forward bool) {
	rng := newRng()
	for _, n := range realSizes {
		t.Run(fmt.Sprint(n), func(t *testing.T) {
			s := cref.NewSetup(n, true)
			nv := s.Ncvec() * 2
			ifac := s.Ifac()
			wa := fclone(s.Twiddle())
			in := randVecs(rng, nv)

			gw1, gw2 := vecs(nv), vecs(nv)
			var o []reg
			ok := catch(t, name, func() {
				if forward {
					o = rfftf1_ps(nv, cloneVecs(in), gw1, gw2, wa, ifac)
				} else {
					o = rfftb1_ps(nv, cloneVecs(in), gw1, gw2, wa, ifac)
				}
			})
			if !ok {
				return
			}

			cw1, cw2 := cbuf(nv), cbuf(nv)
			var ci int
			if forward {
				ci = cref.Rfftf1(nv, cclone(in), cw1, cw2, wa, ifac)
			} else {
				ci = cref.Rfftb1(nv, cclone(in), cw1, cw2, wa, ifac)
			}
			gi := which(o, gw1, gw2)
			if gi != ci {
				t.Errorf("%s: result in work%d, c has it in work%d", name, gi+1, ci+1)
				return
			}
			cmp(t, name, degrade(o), [][]float32{cw1, cw2}[ci], false)
		})
	}
}

func TestRfftf1(t *testing.T) { testRealDriver(t, "rfftf1_ps", true) }
func TestRfftb1(t *testing.T) { testRealDriver(t, "rfftb1_ps", false) }

func TestCfftf1(t *testing.T) {
	rng := newRng()
	for _, n := range complexSizes {
		for _, isign := range []int{-1, 1} {
			t.Run(fmt.Sprintf("%d/isign=%d", n, isign), func(t *testing.T) {
				s := cref.NewSetup(n, false)
				ncvec := s.Ncvec()
				ifac := s.Ifac()
				wa := fclone(s.Twiddle())
				in := randVecs(rng, 2*ncvec)

				gw1, gw2 := vecs(2*ncvec), vecs(2*ncvec)
				var o []reg
				if !catch(t, "cfftf1_ps", func() { o = cfftf1_ps(ncvec, cloneVecs(in), gw1, gw2, wa, ifac, isign) }) {
					return
				}
				cw1, cw2 := cbuf(2*ncvec), cbuf(2*ncvec)
				ci := cref.Cfftf1(ncvec, cclone(in), cw1, cw2, wa, ifac, isign)
				gi := which(o, gw1, gw2)
				if gi != ci {
					t.Errorf("cfftf1_ps: result in work%d, c has it in work%d", gi+1, ci+1)
					return
				}
				cmp(t, "cfftf1_ps", degrade(o), [][]float32{cw1, cw2}[ci], false)
			})
		}
	}
}

func TestDecompose(t *testing.T) {
	for _, ntryh := range [][]int{{4, 2, 3, 5, 0}, {5, 3, 4, 2, 0}} {
		for n := 1; n <= 5000; n++ {
			m := n
			for _, f := range []int{2, 3, 5} {
				for m%f == 0 {
					m /= f
				}
			}
			if m != 1 {
				continue
			}
			gifac := make([]int, IfacMaxSize)
			cifac := make([]int, cref.IfacMaxSize)
			var gnf int
			name := fmt.Sprintf("decompose(%d, %v)", n, ntryh)
			if !catch(t, name, func() { gnf = decompose(n, gifac, ntryh) }) {
				continue
			}
			cnf := cref.Decompose(n, cifac, ntryh)
			if gnf != cnf {
				t.Errorf("%s: go returned %d factors, c %d", name, gnf, cnf)
				continue
			}
			cmpInts(t, name, gifac[:cnf+2], cifac[:cnf+2])
		}
	}
}

func TestTwiddleInit(t *testing.T) {
	type initFunc struct {
		name string
		gof  func(n int, wa []float32, ifac []int)
		cf   func(n int, wa []float32, ifac []int)
		sz   []int
	}
	for _, f := range []initFunc{
		{"rffti1_ps", rffti1_ps, cref.Rffti1, realSizes},
		{"cffti1_ps", cffti1_ps, cref.Cffti1, complexSizes},
	} {
		for _, n := range f.sz {
			nv := n / vlen
			name := fmt.Sprintf("%s(%d)", f.name, nv)
			// twiddles take nv floats for real plans and 2*nv for complex ones.
			// the extra room catches out-of-range writes
			gwa, cwa := make([]float32, 2*nv+8), make([]float32, 2*nv+8)
			gifac, cifac := make([]int, IfacMaxSize), make([]int, cref.IfacMaxSize)
			if !catch(t, name, func() { f.gof(nv, gwa, gifac) }) {
				continue
			}
			f.cf(nv, cwa, cifac)
			cmpInts(t, name+" ifac", gifac, cifac)
			cmp(t, name+" wa", gwa, cwa, false)
		}
	}
}

func TestNewSetup(t *testing.T) {
	type tc struct {
		n    int
		real bool
	}
	var cases []tc
	for _, n := range realSizes {
		cases = append(cases, tc{n, true})
	}
	for _, n := range complexSizes {
		cases = append(cases, tc{n, false})
	}
	// valid multiples that are not 2,3,5-smooth, setup must fail
	cases = append(cases, tc{32 * 7, true}, tc{16 * 11, false})

	for _, c := range cases {
		name := fmt.Sprintf("n=%d,real=%v", c.n, c.real)
		t.Run(name, func(t *testing.T) {
			tr := transformComplex
			if c.real {
				tr = transformReal
			}
			var gs *pffftSetup
			if !catch(t, "pffftNewSetup", func() { gs = pffftNewSetup(c.n, tr) }) {
				return
			}
			cs := cref.NewSetup(c.n, c.real)
			if (gs == nil) != (cs == nil) {
				t.Fatalf("pffftNewSetup: go returned nil: %v, c returned nil: %v", gs == nil, cs == nil)
			}
			if cs == nil {
				return
			}
			if gs.n != cs.N() || gs.ncvec != cs.Ncvec() {
				t.Errorf("n, ncvec: go %d, %d; c %d, %d", gs.n, gs.ncvec, cs.N(), cs.Ncvec())
			}
			cmpInts(t, "ifac", gs.ifac[:], cs.Ifac())
			ce, ctw := cs.E(), cs.Twiddle()
			ge := degrade(gs.e)
			if len(ge) < len(ce) || len(gs.twiddle) < len(ctw) {
				t.Fatalf("go e or twiddle too short: %d, %d; c %d, %d", len(ge), len(gs.twiddle), len(ce), len(ctw))
			}
			cmp(t, "e", ge[:len(ce)], ce, false)
			cmp(t, "twiddle", gs.twiddle[:len(ctw)], ctw, false)
		})
	}
}

func TestReversedCopy(t *testing.T) {
	rng := newRng()
	for n := 1; n <= 8; n++ {
		const stride = 8
		in := randVecs(rng, stride*(n-1)+2)
		gout := vecs(2 * n)
		name := fmt.Sprintf("reversed_copy(n=%d)", n)
		if !catch(t, name, func() { reversed_copy(n, in, stride, gout) }) {
			continue
		}
		cout := cbuf(2 * n)
		cref.ReversedCopy(n, cclone(in), stride, cout)
		cmp(t, name, degrade(gout), cout, true)
	}
}

func TestUnreversedCopy(t *testing.T) {
	rng := newRng()
	for n := 1; n <= 8; n++ {
		for _, stride := range []int{-8, 8} {
			in := randVecs(rng, 2*n)
			size := 8*(n-1) + 2
			off := 0
			if stride < 0 {
				off = -stride * (n - 1)
			}
			gout := vecs(size)
			name := fmt.Sprintf("unreversed_copy(n=%d,stride=%d)", n, stride)
			if !catch(t, name, func() { unreversed_copy(n, in, gout[off:], stride) }) {
				continue
			}
			cout := cbuf(size)
			cref.UnreversedCopy(n, cclone(in), cout, off, stride)
			cmp(t, name, degrade(gout), cout, true)
		}
	}
}

// setups returns a go and a c setup for the same size, failing the test if go can't make one.
func setups(t *testing.T, n int, real bool) (*pffftSetup, *cref.Setup) {
	t.Helper()
	tr := transformComplex
	if real {
		tr = transformReal
	}
	var gs *pffftSetup
	catch(t, "pffftNewSetup", func() { gs = pffftNewSetup(n, tr) })
	if gs == nil {
		t.Fatalf("pffftNewSetup(%d, real=%v) failed, can't continue", n, real)
	}
	return gs, cref.NewSetup(n, real)
}

type sizeCase struct {
	n    int
	real bool
}

func allSizes() []sizeCase {
	var out []sizeCase
	for _, n := range realSizes {
		out = append(out, sizeCase{n, true})
	}
	for _, n := range complexSizes {
		out = append(out, sizeCase{n, false})
	}
	return out
}

// nfloats is the length of a signal or spectrum buffer.
func nfloats(n int, real bool) int {
	if real {
		return n
	}
	return 2 * n
}

func TestZreorder(t *testing.T) {
	rng := newRng()
	for _, c := range allSizes() {
		for _, forward := range []bool{true, false} {
			t.Run(fmt.Sprintf("n=%d,real=%v,forward=%v", c.n, c.real, forward), func(t *testing.T) {
				gs, cs := setups(t, c.n, c.real)
				nf := nfloats(c.n, c.real)
				in := degrade(randVecs(rng, nf/vlen))
				gout := degrade(vecs(nf / vlen))
				if !catch(t, "pffft_zreorder", func() { pffft_zreorder(gs, fclone(in), gout, forward) }) {
					return
				}
				cout := cbuf(nf / vlen)
				cref.Zreorder(cs, fclone(in), cout, forward)
				cmp(t, "pffft_zreorder", gout, cout, true)
			})
		}
	}
}

// processFunc is one of the cplx/real finalize/preprocess functions.
type processFunc struct {
	name string
	real bool
	gof  func(ncvec int, in, out, e []reg)
	cf   func(ncvec int, in, out, e []float32)
}

func TestProcess(t *testing.T) {
	funcs := []processFunc{
		{"pffft_cplx_finalize", false, pffft_cplx_finalize, cref.CplxFinalize},
		{"pffft_cplx_preprocess", false, pffft_cplx_preprocess, cref.CplxPreprocess},
		{"pffft_real_finalize", true, pffft_real_finalize, cref.RealFinalize},
		{"pffft_real_preprocess", true, pffft_real_preprocess, cref.RealPreprocess},
	}
	rng := newRng()
	for _, f := range funcs {
		for _, c := range allSizes() {
			if c.real != f.real {
				continue
			}
			t.Run(fmt.Sprintf("%s/n=%d", f.name, c.n), func(t *testing.T) {
				cs := cref.NewSetup(c.n, c.real)
				ncvec := cs.Ncvec()
				// random e instead of the real coefficients, so that nothing cancels out
				e := randVecs(rng, 6*ncvec/vlen)
				in := randVecs(rng, 2*ncvec)
				gout := vecs(2 * ncvec)
				if !catch(t, f.name, func() { f.gof(ncvec, cloneVecs(in), gout, cloneVecs(e)) }) {
					return
				}
				cout := cbuf(2 * ncvec)
				f.cf(ncvec, cclone(in), cout, cclone(e))
				cmp(t, f.name, degrade(gout), cout, false)
			})
		}
	}
}

func TestRealFinalize4x4(t *testing.T) {
	rng := newRng()
	for _ = range 20 {
		v := randVecs(rng, 2+6+6)
		in0, in1, in, e := v[0], v[1], v[2:8], v[8:14]
		gout := vecs(8)
		if !catch(t, "pffft_real_finalize_4x4", func() { pffft_real_finalize_4x4(in0, in1, cloneVecs(in), cloneVecs(e), gout) }) {
			return
		}
		cout := cbuf(8)
		cref.RealFinalize4x4(cclone(v[0:1]), cclone(v[1:2]), cclone(in), cclone(e), cout)
		if !cmp(t, "pffft_real_finalize_4x4", degrade(gout), cout, false) {
			return
		}
	}
}

func TestRealPreprocess4x4(t *testing.T) {
	rng := newRng()
	for _, first := range []bool{true, false} {
		for _ = range 20 {
			in, e := randVecs(rng, 8), randVecs(rng, 6)
			n := 8
			if first {
				n = 6
			}
			name := fmt.Sprintf("pffft_real_preprocess_4x4(first=%v)", first)
			gout := vecs(n)
			if !catch(t, name, func() { pffft_real_preprocess_4x4(cloneVecs(in), cloneVecs(e), gout, first) }) {
				break
			}
			cout := cbuf(n)
			cref.RealPreprocess4x4(cclone(in), cclone(e), cout, first)
			if !cmp(t, name, degrade(gout), cout, false) {
				break
			}
		}
	}
}

// goBuf returns a buffer for the go transform: the transform realigns its arguments
// with align, so the payload lives at align(buf).
func goBuf(nf int) (buf, payload []float32) {
	buf = degrade(vecs(nf/vlen + 1))
	return buf, align(buf)
}

func TestTransform(t *testing.T) {
	rng := newRng()
	for _, c := range allSizes() {
		for _, forward := range []bool{true, false} {
			for _, ordered := range []int{0, 1} {
				for _, api := range []bool{false, true} {
					for _, inplace := range []bool{false, true} {
						name := fmt.Sprintf("n=%d,real=%v,forward=%v,ordered=%d,api=%v,inplace=%v",
							c.n, c.real, forward, ordered, api, inplace)
						t.Run(name, func(t *testing.T) {
							testTransform(t, rng, c, forward, ordered, api, inplace)
						})
					}
				}
			}
		}
	}
}

// testTransform runs pffft_transform_internal, or pffft_transform/pffft_transform_ordered
// when api is set.
func testTransform(t *testing.T, rng *rand.Rand, c sizeCase, forward bool, ordered int, api, inplace bool) {
	gs, cs := setups(t, c.n, c.real)
	nf := nfloats(c.n, c.real)
	ncvec := cs.Ncvec()
	in := randFloats(rng, nf)

	gin, gpayload := goBuf(nf)
	copy(gpayload, in)
	gout := gin
	if !inplace {
		gout, _ = goBuf(nf)
	}
	gwork := degrade(vecs(2 * ncvec))
	var aout []float32
	ok := catch(t, "transform", func() {
		switch {
		case api && ordered == 1:
			_, aout = pffft_transform_ordered(gs, gin, gout, gwork, forward)
		case api:
			_, aout = pffft_transform(gs, gin, gout, gwork, forward)
		default:
			_, aout = pffft_transform_internal(gs, gin, gout, getAsAligned(gwork), forward, ordered)
		}
	})
	if !ok {
		return
	}

	cin := cbuf(nf / vlen)
	copy(cin, in)
	cout := cin
	if !inplace {
		cout = cbuf(nf / vlen)
	}
	cwork := cbuf(2 * ncvec)
	switch {
	case api && ordered == 1:
		cref.TransformOrdered(cs, cin, cout, cwork, forward)
	case api:
		cref.Transform(cs, cin, cout, cwork, forward)
	default:
		cref.TransformInternal(cs, cin, cout, cwork, forward, ordered == 1)
	}
	cmp(t, "transform", aout[:nf], cout, false)
}

// make sure the c side is sane before blaming go, using a naive dft as the oracle
func TestCrefSanity(t *testing.T) {
	rng := newRng()
	const n = 96
	cs := cref.NewSetup(n, true)
	in := cbuf(n / vlen)
	copy(in, randFloats(rng, n))
	out := cbuf(n / vlen)
	cref.TransformOrdered(cs, in, out, cbuf(n/vlen), true)
	want := make([]float32, n)
	for k := 0; k <= n/2; k++ {
		var re, im float64
		for j := range n {
			a := -2 * math.Pi * float64(j*k) / n
			re += float64(in[j]) * math.Cos(a)
			im += float64(in[j]) * math.Sin(a)
		}
		switch k {
		case 0:
			want[0] = float32(re)
		case n / 2:
			want[1] = float32(re)
		default:
			want[2*k], want[2*k+1] = float32(re), float32(im)
		}
	}
	cmp(t, "cref ordered forward vs naive dft", out, want, false)
}
